// Extrait l'essentiel des deux formes d'événements Stripe.
const b = $json.body || $json;
const type = String(b.type || '');
const o = (b.data && b.data.object) || {};
const email = String(o.customer_details?.email || o.customer_email || '').toLowerCase().trim();
const cents = Number(o.amount_total ?? o.amount_paid ?? 0);
const amount = Math.round(cents) / 100;
const currency = String(o.currency || 'eur').toUpperCase();
const label = type.includes('invoice') ? 'facture' : 'paiement';
if (!email || !amount) return [];
return [{ json: { email, amount, currency, label } }];
